-- 143: Original BrillaPrep WASSCE BrillaPrep transitional Auto Mechanics beta content blueprint questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_143_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_143_guard;
INSERT INTO _migration_143_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_001' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_1' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which tool applies a manufacturer-specified tightening torque to an engine fastener?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A torque wrench","B. A breaker bar","C. A ring spanner","D. An impact wrench"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A torque wrench is calibrated to apply a selected turning moment, helping prevent fasteners from being left loose or overstressed. Therefore the correct answer is A: A torque wrench.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_001' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_143_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_002' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_1' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the safest first action before raising a vehicle with a workshop jack?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Raise one side before applying the parking brake","B. Park on firm level ground and secure the vehicle against movement","C. Use the nearest body panel as the lifting point","D. Rely on the hydraulic jack without wheel chocks"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Stable ground, wheel chocks and the parking brake reduce unintended movement before lifting; axle stands are then required before working underneath. Therefore the correct answer is B: Park on firm level ground and secure the vehicle against movement.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_002' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_143_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_003' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_1' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which measuring instrument is most suitable for checking a crankshaft journal diameter accurately?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A vernier depth gauge","B. A dial bore gauge","C. An outside micrometer","D. A feeler gauge"]' AND q.correct_answer IS 'C' AND q.explanation IS 'An outside micrometer measures external diameters precisely enough to compare a journal with its wear and service limits. Therefore the correct answer is C: An outside micrometer.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_003' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_143_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_004' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_1' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should compressed air not be directed at a person in an automotive workshop?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Its pressure is too low to move workshop debris","B. It is safe when the nozzle is held at arm length","C. Only the noise from the air jet presents a hazard","D. It can drive particles into the eyes or body and cause serious injury"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Compressed air can propel debris at high speed or penetrate tissue, so guarded nozzles, eye protection and safe cleaning methods are essential. Therefore the correct answer is D: It can drive particles into the eyes or body and cause serious injury.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_004' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_143_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_005' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_1' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does a vehicle hoist safety lock do after the vehicle is raised?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It mechanically supports the lift against unintended lowering","B. It maintains support only by trapping hydraulic pressure","C. It compensates for unequal vehicle weight automatically","D. It prevents the hoist motor from restarting unexpectedly"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The mechanical lock carries or secures the raised structure so a hydraulic pressure loss does not allow uncontrolled descent. Therefore the correct answer is A: It mechanically supports the lift against unintended lowering.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_005' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
